  "選擇本機音樂": { en: "Choose music from your device", ja: "端末から音楽を選択", fr: "Choisir un fichier audio", de: "Musikdatei auswählen", it: "Scegli musica dal dispositivo", es: "Elegir música del dispositivo" },
