  "恢復預設值": { en: "Reset to defaults", ja: "初期設定に戻す", fr: "Rétablir les valeurs par défaut", de: "Auf Standardwerte zurücksetzen", it: "Ripristina valori predefiniti", es: "Restablecer valores predeterminados" },
