  "請選擇可讀取的圖片檔案。": { en: "Choose a readable image file.", ja: "読み取り可能な画像ファイルを選択してください。", fr: "Choisissez un fichier image lisible.", de: "Wähle eine lesbare Bilddatei aus.", it: "Scegli un file immagine leggibile.", es: "Elige un archivo de imagen legible." },
  "背景影片請小於 1 GB。": { en: "Background videos must be smaller than 1 GB.", ja: "背景動画は1 GB未満にしてください。", fr: "Les vidéos d’arrière-plan doivent faire moins de 1 Go.", de: "Hintergrundvideos müssen kleiner als 1 GB sein.", it: "I video di sfondo devono pesare meno di 1 GB.", es: "Los vídeos de fondo deben ocupar menos de 1 GB." },
  "背景圖片請小於 30 MB。": { en: "Background images must be smaller than 30 MB.", ja: "背景画像は30 MB未満にしてください。", fr: "Les images d’arrière-plan doivent faire moins de 30 Mo.", de: "Hintergrundbilder müssen kleiner als 30 MB sein.", it: "Le immagini di sfondo devono pesare meno di 30 MB.", es: "Las imágenes de fondo deben ocupar menos de 30 MB." },
  "請選擇 JPG、PNG、WebP、MP4、MOV 或 WebM。": { en: "Choose a JPG, PNG, WebP, MP4, MOV, or WebM file.", ja: "JPG、PNG、WebP、MP4、MOV、またはWebMファイルを選択してください。", fr: "Choisissez un fichier JPG, PNG, WebP, MP4, MOV ou WebM.", de: "Wähle eine JPG-, PNG-, WebP-, MP4-, MOV- oder WebM-Datei aus.", it: "Scegli un file JPG, PNG, WebP, MP4, MOV o WebM.", es: "Elige un archivo JPG, PNG, WebP, MP4, MOV o WebM." },
  "背景影片沒有可顯示的畫面。": { en: "The background video has no displayable frames.", ja: "背景動画に表示できるフレームがありません。", fr: "La vidéo d’arrière-plan ne contient aucune image affichable.", de: "Das Hintergrundvideo enthält keine anzeigbaren Bilder.", it: "Il video di sfondo non contiene fotogrammi visualizzabili.", es: "El vídeo de fondo no contiene fotogramas visibles." },
  "背景影片無法載入。": { en: "Could not load the background video.", ja: "背景動画を読み込めませんでした。", fr: "Impossible de charger la vidéo d’arrière-plan.", de: "Das Hintergrundvideo konnte nicht geladen werden.", it: "Impossibile caricare il video di sfondo.", es: "No se pudo cargar el vídeo de fondo." },
  "請選擇可讀取的背景素材。": { en: "Choose a readable background file.", ja: "読み取り可能な背景素材を選択してください。", fr: "Choisissez un fichier d’arrière-plan lisible.", de: "Wähle eine lesbare Hintergrunddatei aus.", it: "Scegli un file di sfondo leggibile.", es: "Elige un archivo de fondo legible." },
  "播放失敗，請重新載入音樂。": { en: "Playback failed. Reload the music and try again.", ja: "再生に失敗しました。音楽を再読み込みしてください。", fr: "La lecture a échoué. Rechargez le morceau et réessayez.", de: "Wiedergabe fehlgeschlagen. Lade die Musik neu und versuche es erneut.", it: "Riproduzione non riuscita. Ricarica la musica e riprova.", es: "Falló la reproducción. Vuelve a cargar la música e inténtalo de nuevo." },
  "正在匯出 0%": { en: "Exporting 0%", ja: "書き出し中 0%", fr: "Exportation : 0 %", de: "Export 0%", it: "Esportazione 0%", es: "Exportando 0%" },
  "匯出失敗，請降低解析度再試。": { en: "Export failed. Try a lower resolution.", ja: "書き出しに失敗しました。解像度を下げてお試しください。", fr: "Échec de l’export. Essayez une résolution plus faible.", de: "Export fehlgeschlagen. Versuche eine niedrigere Auflösung.", it: "Esportazione non riuscita. Prova una risoluzione inferiore.", es: "Falló la exportación. Prueba con una resolución menor." },
  "裁剪失敗，請重新設定範圍。": { en: "Trim failed. Set the range again.", ja: "トリミングに失敗しました。範囲を設定し直してください。", fr: "Échec du rognage. Définissez à nouveau la plage.", de: "Zuschnitt fehlgeschlagen. Lege den Bereich erneut fest.", it: "Taglio non riuscito. Imposta di nuovo l’intervallo.", es: "Falló el recorte. Vuelve a configurar el intervalo." },
  "字幕檔請小於 5 MB。": { en: "Subtitle files must be smaller than 5 MB.", ja: "字幕ファイルは5 MB未満にしてください。", fr: "Les fichiers de sous-titres doivent faire moins de 5 Mo.", de: "Untertiteldateien müssen kleiner als 5 MB sein.", it: "I file dei sottotitoli devono pesare meno di 5 MB.", es: "Los archivos de subtítulos deben ocupar menos de 5 MB." },
  "請選擇 SRT、ASS 或 TXT 字幕檔。": { en: "Choose an SRT, ASS, or TXT subtitle file.", ja: "SRT、ASS、またはTXT形式の字幕ファイルを選択してください。", fr: "Choisissez un fichier de sous-titres SRT, ASS ou TXT.", de: "Wähle eine SRT-, ASS- oder TXT-Untertiteldatei aus.", it: "Scegli un file di sottotitoli SRT, ASS o TXT.", es: "Elige un archivo de subtítulos SRT, ASS o TXT." },
  "無法讀取文字編碼，請將字幕另存為 UTF-8。": { en: "Could not read the text encoding. Save the subtitles as UTF-8.", ja: "テキストの文字コードを読み込めません。字幕をUTF-8で保存してください。", fr: "Impossible de lire l’encodage du texte. Enregistrez les sous-titres en UTF-8.", de: "Textkodierung konnte nicht gelesen werden. Speichere die Untertitel als UTF-8.", it: "Impossibile leggere la codifica del testo. Salva i sottotitoli in UTF-8.", es: "No se pudo leer la codificación del texto. Guarda los subtítulos en UTF-8." },
  "無法讀取字幕檔。": { en: "Could not read the subtitle file.", ja: "字幕ファイルを読み込めませんでした。", fr: "Impossible de lire le fichier de sous-titres.", de: "Untertiteldatei konnte nicht gelesen werden.", it: "Impossibile leggere il file dei sottotitoli.", es: "No se pudo leer el archivo de subtítulos." },
  "圖片儲存後仍過大，請改用較簡單的識別圖片。": { en: "The image is still too large after processing. Try a simpler branding image.", ja: "処理後も画像サイズが大きすぎます。シンプルなロゴ画像をお試しください。", fr: "L’image reste trop volumineuse après traitement. Essayez une image de signature plus simple.", de: "Das Bild ist auch nach der Verarbeitung noch zu groß. Verwende ein einfacheres Kennzeichnungsbild.", it: "L’immagine è ancora troppo grande dopo l’elaborazione. Prova un’immagine identificativa più semplice.", es: "La imagen sigue siendo demasiado grande tras procesarla. Prueba con una imagen identificativa más sencilla." },
  "無法讀取識別圖片。": { en: "Could not read the branding image.", ja: "ロゴ画像を読み込めませんでした。", fr: "Impossible de lire l’image de signature.", de: "Kennzeichnungsbild konnte nicht gelesen werden.", it: "Impossibile leggere l’immagine identificativa.", es: "No se pudo leer la imagen identificativa." },
  "關閉訊息": { en: "Dismiss message", ja: "メッセージを閉じる", fr: "Fermer le message", de: "Meldung schließen", it: "Chiudi messaggio", es: "Cerrar mensaje" },
  "無法讀取音樂": { en: "Could not read music", ja: "音楽を読み込めませんでした", fr: "Impossible de lire la musique", de: "Musik konnte nicht gelesen werden", it: "Impossibile leggere la musica", es: "No se pudo leer la música" },
  "裁剪失敗": { en: "Trim failed", ja: "トリミングに失敗しました", fr: "Échec du rognage", de: "Zuschnitt fehlgeschlagen", it: "Taglio non riuscito", es: "Falló el recorte" },
  "字幕字體大小": { en: "Subtitle font size", ja: "字幕の文字サイズ", fr: "Taille des sous-titres", de: "Untertitelschriftgröße", it: "Dimensione carattere sottotitoli", es: "Tamaño de fuente de subtítulos" },
