  "影片 · VP9 / Opus": { en: "Video · VP9 / Opus", ja: "動画 · VP9 / Opus", fr: "Vidéo · VP9 / Opus", de: "Video · VP9 / Opus", it: "Video · VP9 / Opus", es: "Vídeo · VP9 / Opus" },
  "純音訊 · MP3 192 kbps": { en: "Audio only · MP3 192 kbps", ja: "音声のみ · MP3 192 kbps", fr: "Audio uniquement · MP3 192 kbit/s", de: "Nur Audio · MP3 192 kbit/s", it: "Solo audio · MP3 192 kbps", es: "Solo audio · MP3 192 kbps" },
  "純音訊 · AAC 192 kbps": { en: "Audio only · AAC 192 kbps", ja: "音声のみ · AAC 192 kbps", fr: "Audio uniquement · AAC 192 kbit/s", de: "Nur Audio · AAC 192 kbit/s", it: "Solo audio · AAC 192 kbps", es: "Solo audio · AAC 192 kbps" },
  "純音訊 · FLAC 無損編碼": { en: "Audio only · FLAC lossless", ja: "音声のみ · FLACロスレス", fr: "Audio uniquement · FLAC sans perte", de: "Nur Audio · FLAC verlustfrei", it: "Solo audio · FLAC senza perdita", es: "Solo audio · FLAC sin pérdida" },
