  "不支援的輸出格式。": { en: "Unsupported output format.", ja: "未対応の出力形式です。", fr: "Format de sortie non pris en charge.", de: "Nicht unterstütztes Ausgabeformat.", it: "Formato di uscita non supportato.", es: "Formato de salida no compatible." },
  "無效的影片設定。": { en: "Invalid video settings.", ja: "動画設定が無効です。", fr: "Paramètres vidéo invalides.", de: "Ungültige Videoeinstellungen.", it: "Impostazioni video non valide.", es: "La configuración de vídeo no es válida." },
