  "此瀏覽器無法編碼 {0}，請使用最新版 Chrome 或 Edge 再試。檔案不會改送至伺服器。": { en: "This browser cannot encode {0}. Try the latest version of Chrome or Edge. Your file will not be uploaded to a server.", ja: "このブラウザーでは{0}をエンコードできません。最新版のChromeまたはEdgeをお試しください。ファイルがサーバーに送信されることはありません。", fr: "Ce navigateur ne peut pas encoder {0}. Essayez la dernière version de Chrome ou Edge. Votre fichier ne sera pas envoyé sur un serveur.", de: "Dieser Browser kann {0} nicht codieren. Versuche die aktuelle Version von Chrome oder Edge. Deine Datei wird nicht auf einen Server hochgeladen.", it: "Questo browser non può codificare {0}. Prova l’ultima versione di Chrome o Edge. Il file non verrà caricato su un server.", es: "Este navegador no puede codificar {0}. Prueba la última versión de Chrome o Edge. El archivo no se subirá a ningún servidor." },
  "請設定有效的裁剪範圍，結束時間必須大於開始時間。": { en: "Set a valid trim range. The end time must be after the start time.", ja: "有効なトリミング範囲を設定してください。終了時刻は開始時刻より後にしてください。", fr: "Définissez une plage de rognage valide. La fin doit être postérieure au début.", de: "Lege einen gültigen Zuschnittbereich fest. Die Endzeit muss nach der Startzeit liegen.", it: "Imposta un intervallo di taglio valido. L’ora di fine deve essere successiva a quella iniziale.", es: "Configura un intervalo de recorte válido. La hora final debe ser posterior a la inicial." },
  "背景素材已載入，但無法保存到瀏覽器：{0}": { en: "Background loaded, but could not be saved in the browser: {0}", ja: "背景素材を読み込みましたが、ブラウザーに保存できませんでした：{0}", fr: "Arrière-plan chargé, mais impossible de l’enregistrer dans le navigateur : {0}", de: "Hintergrund geladen, konnte aber nicht im Browser gespeichert werden: {0}", it: "Sfondo caricato, ma non è stato possibile salvarlo nel browser: {0}", es: "Fondo cargado, pero no se pudo guardar en el navegador: {0}" },
  "字幕已載入，但無法保存到瀏覽器：{0}": { en: "Subtitles loaded, but could not be saved in the browser: {0}", ja: "字幕を読み込みましたが、ブラウザーに保存できませんでした：{0}", fr: "Sous-titres chargés, mais impossible de les enregistrer dans le navigateur : {0}", de: "Untertitel geladen, konnten aber nicht im Browser gespeichert werden: {0}", it: "Sottotitoli caricati, ma non è stato possibile salvarli nel browser: {0}", es: "Subtítulos cargados, pero no se pudieron guardar en el navegador: {0}" },
