  "無法還原保存的背景素材：{0}": { en: "Could not restore the saved background: {0}", ja: "保存した背景素材を復元できませんでした：{0}", fr: "Impossible de restaurer l’arrière-plan enregistré : {0}", de: "Gespeicherter Hintergrund konnte nicht wiederhergestellt werden: {0}", it: "Impossibile ripristinare lo sfondo salvato: {0}", es: "No se pudo restaurar el fondo guardado: {0}" },
  "無法還原保存的字幕：{0}": { en: "Could not restore saved subtitles: {0}", ja: "保存した字幕を復元できませんでした：{0}", fr: "Impossible de restaurer les sous-titres enregistrés : {0}", de: "Gespeicherte Untertitel konnten nicht wiederhergestellt werden: {0}", it: "Impossibile ripristinare i sottotitoli salvati: {0}", es: "No se pudieron restaurar los subtítulos guardados: {0}" },
  "拖曳平移裁剪範圍，長度 {0}": { en: "Drag to move the trim range, length {0}", ja: "ドラッグしてトリミング範囲を移動、長さ {0}", fr: "Faites glisser pour déplacer la plage de rognage, durée {0}", de: "Ziehen, um den Zuschnittbereich zu verschieben, Länge {0}", it: "Trascina per spostare l’intervallo di taglio, durata {0}", es: "Arrastra para mover el intervalo de recorte, duración {0}" },
