  "JPG · PNG · WebP · 30 MB 以內": { en: "JPG · PNG · WebP · up to 30 MB", ja: "JPG · PNG · WebP · 最大 30 MB", fr: "JPG · PNG · WebP · 30 Mo max.", de: "JPG · PNG · WebP · bis 30 MB", it: "JPG · PNG · WebP · fino a 30 MB", es: "JPG · PNG · WebP · hasta 30 MB" },
